// ==========================================
// ★ 마법사 확장 2/4 — 동료 · 미니게임 중심
// index.html 에서 epic-mage-1.js 다음에 불러온다
// ==========================================

epicSlot('gate', 'mage').push(
{ title:'성문 — 둘이 닫는다',
  text:`닫히지 않은 이름이 하나 있다.<br><br>
    혼자 닫으려면 읽어야 한다. 읽으면 불린다.<br>
    둘이면 안 읽고 닫을 수 있다.<br><br>
    하나가 눈을 가리고 하나가 손을 이끈다.`,
  opts:[
    { l:'① 동료가 손을 이끈다.', co:'sync',
      coOpt:{ ask:'제 눈을 가리고 손을 그 자리로 이끌어 주십시오. 저는 안 봅니다.', sec:65, p:1100,
        text:`안 읽고 닫으려면 둘이 필요하다.`,
        doneText:`저쪽이 눈을 가렸다. 손목을 잡고 받침으로 이끌었다.<br><br>손끝이 글자에 닿는다. 모양이 만져진다. 안 읽으려고 애썼다.<br>왼쪽에서 오른쪽으로 그었다. 닫는 방향으로.<br><br>눈을 떴다. 줄이 그어져 있다. 스물넷이 다 닫혔다.<br>읽지 않고 닫았다. 마법사가 제일 하고 싶어 하는 일이다.`,
        failText:`혼자 하려니 봐야 한다.<br><br>눈을 감고 더듬었다. 손이 엉뚱한 데를 긋는다.<br>지웠다. 닫는 줄은 잘못 그으면 여는 줄이 된다.<br>그만뒀다.` },
      good:`닫았다.`, bad:`못 닫았다.`, flag:'sealedBlind' },
    { l:'② 닫힌 줄의 순서를 짚는다.', mini:'star', miniOpt:{ p:750, n:7, sec:18 },
      good:`줄이 파인 깊이로 순서를 짚었다. 일곱 개.<br><br>맞췄다. 갈수록 얕아진다. 힘이 빠졌다.<br>스물셋을 연달아 닫으면 그렇게 된다.<br><br>마지막 몇은 거의 안 파였다. 그래도 닫긴 닫혔다.`, flag:'fadingSeals',
      bad:`깊이가 뒤섞여 있다.<br><br>순서를 못 잡겠다. 한 번에 안 닫은 모양이다.<br>그만뒀다.` }
  ] }
);

epicSlot('tower', 'mage').push(
{ title:'탑 — 둘이 지운다',
  text:`벽에 잘못 쓴 문장이 있다.<br><br>
    지우려면 처음과 끝을 동시에 눌러야 한다.<br>
    한쪽만 누르면 남은 쪽이 이어 쓴다.<br><br>
    문장은 끊기면 스스로 잇는다.`,
  opts:[
    { l:'① 동료와 양 끝을 누른다.', co:'sync',
      coOpt:{ ask:'저쪽 끝을 손바닥으로 눌러 주십시오. 제가 셋을 세면 같이 뗍니다.', sec:60, p:1050,
        text:`한쪽만 누르면 남은 쪽이 이어 쓴다.`,
        doneText:`양 끝을 눌렀다. 셋을 세고 같이 뗐다.<br><br>문장이 흐려진다. 가운데부터 사라진다.<br>양쪽이 동시에 끊기면 이을 데가 없다.<br><br>다 지워졌다. 벽이 그냥 벽이 됐다.<br>저쪽이 손바닥을 봤다. 글자가 안 옮았다.`,
        failText:`혼자 한쪽만 눌렀다.<br><br>누른 쪽이 흐려지고 반대쪽이 진해진다.<br>이어 쓰고 있다. 손을 뗐다. 원래대로 돌아왔다.` },
      good:`지웠다.`, bad:`도로 이어졌다.`, flag:'erasedBothEnds' },
    { l:'② 문장의 힘을 견준다.', mini:'scale', miniOpt:{ p:800, target:26, pool:[4,6,7,9,11,13] },
      good:`문장 조각들의 무게를 견줬다.<br><br>맞췄다. 짧은 조각이 더 무겁다.<br>짧을수록 강하다는 게 저울에도 나온다.<br><br>제일 짧은 조각이 제일 무겁다. 세 글자짜리다.`, flag:'shortestHeaviest',
      bad:`저울이 안 맞는다.<br><br>올릴 때마다 무게가 바뀐다. 문장이 읽히는 중이라 그렇다.<br>그만뒀다.` }
  ] }
);

epicSlot('temple', 'mage').push(
{ title:'신전 — 둘이 묶는다',
  text:`함을 네 번 묶었다.<br><br>
    다만 한 손으로 묶은 매듭은 한 손으로 풀린다.<br>
    손이 둘이면 다르다.<br><br>
    묶는 손이 여럿이면 안 풀린다.`,
  opts:[
    { l:'① 동료와 같이 묶는다.', co:'handoff',
      coOpt:{ ask:'끈 한쪽을 잡아 주십시오. 같이 묶으면 혼자는 못 풉니다.', sec:60, p:1000,
        text:`묶는 손이 여럿이면 안 풀린다.`,
        doneText:`둘이 끝을 하나씩 잡고 당겨 묶었다.<br><br>매듭이 두 방향에서 조여진다. 한 손으로는 이 각도가 안 나온다.<br>다섯 번째 매듭이 됐다.<br><br>당겨 봤다. 안 풀린다. 둘이 같이 당겨야 풀린다.<br>저쪽 손이 필요해졌다는 뜻이다. 그게 목적이었다.`,
        failText:`혼자 한 번 더 묶었다. 다섯 번이 됐다.<br><br>수만 늘었다. 한 손으로 묶은 건 한 손으로 풀린다.<br>수가 문제가 아니었다.` },
      good:`둘이 묶었다.`, bad:`수만 늘었다.`, flag:'twoHandedKnot' },
    { l:'② 매듭 순서를 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`묶인 순서를 짚었다. 여섯 겹.<br><br>맞췄다. 안쪽부터 바깥으로.<br>안쪽 것이 제일 단단하다. 처음 묶은 것.<br><br>처음 묶은 사람이 제일 세게 묶었다.`, flag:'innermostTightest',
      bad:`겹이 엉켜 있다.<br><br>순서를 못 잡겠다. 여럿이 제각각 묶었다.<br>그만뒀다.` }
  ] }
);

epicSlot('ruin', 'mage').push(
{ title:'폐허 — 둘이 지킨다',
  text:`깨진 진에서 뭔가 새고 있다.<br><br>
    안 이으면 계속 샌다. 이으면 고인다.<br>
    둘 다 나쁘다.<br><br>
    마법사는 세 번째 방법을 안다. 새는 쪽을 돌리는 것.`,
  opts:[
    { l:'① 동료와 길을 낸다.', co:'sync',
      coOpt:{ ask:'끊긴 데에서 밖으로 홈을 파 주십시오. 제가 방향을 잡겠습니다.', sec:65, p:1050,
        text:`막지 말고 돌린다.`,
        doneText:`이쪽이 방향을 잡고 저쪽이 홈을 팠다.<br><br>끊긴 데서 회랑 밖으로 얕은 줄이 이어진다.<br>새던 것이 그쪽으로 흐른다. 고이지 않는다.<br><br>마법은 대개 막는 일이 아니라 흘려보내는 일이다.<br>저쪽이 그 말을 되뇌었다. 마음에 든 모양이다.`,
        failText:`혼자 홈을 팠다. 방향이 안 잡힌다.<br><br>판 데로 안 흐른다. 원 쪽으로 도로 고인다.<br>메웠다.` },
      good:`흘려보냈다.`, bad:`고였다.`, flag:'channeledLeak' },
    { l:'② 원의 균형을 맞춘다.', mini:'scale', miniOpt:{ p:800, target:24, pool:[3,5,7,8,10,12] },
      good:`원 위 네 방위의 돌 무게를 견줬다.<br><br>맞췄다. 한쪽만 가볍다. 무너진 쪽이다.<br>그쪽에 돌을 보태니 원이 덜 흔들린다.<br><br>안 이었는데 덜 샌다. 균형이 잡히면 그렇게 된다.`, flag:'rebalancedCircle',
      bad:`맞추는 족족 기운다.<br><br>보탠 만큼 반대쪽이 가벼워진다.<br>그만뒀다.` }
  ] }
);

epicSlot('forest', 'mage').push(
{ title:'검은 숲 — 흩어서 본다',
  text:`나무마다 글자가 하나씩이다.<br><br>
    순서대로 보면 문장이 된다.<br>
    혼자 보면 순서가 생긴다. 걸어가는 순서로.<br><br>
    둘이 흩어지면 순서가 안 생긴다.`,
  opts:[
    { l:'① 동료와 흩어져 본다.', co:'sync',
      coOpt:{ ask:'반대쪽부터 봐 주십시오. 순서를 안 맞추는 게 목적입니다.', sec:60, p:1000,
        text:`순서가 생기면 문장이 된다.`,
        doneText:`갈라져서 반대쪽부터 봤다.<br><br>합쳐 보니 순서가 뒤엉켰다. 뜻이 안 잡힌다.<br>저쪽이 본 것과 이쪽이 본 것을 서로 안 말했다.<br><br>말하면 이어진다. 안 이어지게 두는 게 목적이었다.<br>종이에도 따로따로 적어 두 사람이 나눠 가졌다.`,
        failText:`혼자 한 방향으로 걸으며 봤다.<br><br>순서가 생긴다. 다섯 글자쯤에서 뜻이 잡히기 시작했다.<br>눈을 감고 걸었다. 나무에 부딪혔다.` },
      good:`뜻이 안 잡혔다.`, bad:`잡히기 시작했다.`, flag:'brokeSequence' },
    { l:'② 글자 모양만 베낀다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`획이 많은 순서로 여섯 그루를 짚었다.<br><br>맞췄다. 획 수로만 보면 뜻이 안 잡힌다.<br>뜻이 아니라 모양으로 세는 방법이다.<br><br>마법사가 위험한 글자를 다룰 때 쓴다.`, flag:'countedStrokes',
      bad:`획을 세는데 뜻이 먼저 온다.<br><br>세기 전에 읽힌다. 눈을 돌렸다.` }
  ] }
);

epicSlot('grave', 'mage').push(
{ title:'묘지 — 둘이 확인한다',
  text:`한 비석에 갈아 낸 자국이 있었다.<br><br>
    새겼다가 지운 것이다.<br>
    혼자 찾으면 오래 걸리고, 오래 보면 읽힌다.<br><br>
    둘이 나눠 보면 짧게 끝난다.`,
  opts:[
    { l:'① 동료와 나눠 훑는다.', co:'handoff',
      coOpt:{ ask:'저쪽 열둘을 손으로 훑어 주십시오. 거친 데가 있으면 말만 하시고.', sec:60, p:1000,
        text:`오래 보면 읽힌다.`,
        doneText:`손으로만 훑었다. 눈은 안 썼다.<br><br>저쪽이 하나를 찾았다. 가운데 줄 끝에서 셋째.<br>거칠다고만 했다. 모양은 안 봤다고 했다.<br><br>이쪽도 안 봤다. 어느 비석인지만 알면 됐다.<br>표를 하고 물러났다.`,
        failText:`혼자 스물셋을 훑었다. 오래 걸렸다.<br><br>훑는 동안 손끝으로 모양이 잡힌다.<br>세 글자쯤 알겠다. 손을 뗐다.` },
      good:`모양은 안 봤다.`, bad:`세 글자를 알았다.`, flag:'foundByTouch' },
    { l:'② 비석 배열을 짚는다.', mini:'star', miniOpt:{ p:750, n:7, sec:18 },
      good:`세운 순서로 일곱을 짚었다. 이끼로 알 수 있다.<br><br>맞췄다. 가장자리부터 가운데로 채워졌다.<br>갈아 낸 하나가 제일 나중이다.<br><br>마지막에 새겼다가 마지막에 지웠다.`, flag:'lastCarvedErased',
      bad:`이끼가 고르다.<br><br>순서를 못 잡겠다.<br>그만뒀다.` }
  ] }
);

epicSlot('castle', 'mage').push(
{ title:'성 — 둘이 본다',
  text:`벽 글자가 안 말랐다.<br><br>
    쓰는 중이라는 뜻이다.<br>
    혼자 보면 다음 획이 어디로 갈지 짐작하게 된다.<br><br>
    짐작하면 그쪽으로 그어진다.`,
  opts:[
    { l:'① 동료가 시선을 끊어 준다.', co:'standin',
      coOpt:{ ask:'제가 벽을 오래 보면 말을 걸어 주십시오. 아무 말이나.', sec:60, p:1050,
        text:`짐작하면 그쪽으로 그어진다.`,
        doneText:`보다 보면 저쪽이 말을 걸었다. 날씨 이야기를 했다.<br><br>여기 날씨는 늘 같은데 그래도 이야기가 됐다.<br>세 번 끊겼다. 세 번 다 짐작이 안 섰다.<br><br>벽을 다시 보니 획이 안 늘었다.<br>짐작 안 하면 안 늘어난다.`,
        failText:`혼자 봤다. 다음 획이 어디로 갈지 보인다.<br><br>보이는 대로 그어진다. 한 획.<br>눈을 감았다. 감고도 보였다.` },
      good:`안 늘었다.`, bad:`한 획 늘었다.`, flag:'interruptedGaze' },
    { l:'② 글자의 나이를 견준다.', mini:'scale', miniOpt:{ p:750, target:22, pool:[3,4,6,7,9,12] },
      good:`마른 정도로 순서를 잡았다.<br><br>맞췄다. 앞쪽은 아주 오래됐고 끝쪽은 방금이다.<br>한 문장을 몇 해에 걸쳐 쓰고 있다.<br><br>천천히 쓰는 사람이다. 아니면 천천히 쓸 수밖에 없거나.`, flag:'slowWriting',
      bad:`마른 정도가 다 같다.<br><br>한꺼번에 쓴 것처럼. 그럴 수는 없는데.<br>그만뒀다.` }
  ] }
);

epicSlot('lake', 'mage').push(
{ title:'거울 호수 — 둘이 읽는다',
  text:`수면 글자는 양쪽으로 읽힌다.<br><br>
    혼자 읽으면 한 방향씩 읽어야 한다.<br>
    두 번 읽으면 두 번 걸린다.<br><br>
    둘이 동시에 읽으면 한 번이다.`,
  opts:[
    { l:'① 동료와 동시에 읽는다.', co:'sync',
      coOpt:{ ask:'거꾸로 읽어 주십시오. 제가 바로 읽겠습니다. 동시에 시작합니다.', sec:65, p:1100,
        text:`두 번 읽으면 두 번 걸린다.`,
        doneText:`동시에 시작했다. 저쪽이 끝에서, 이쪽이 앞에서.<br><br>가운데서 만났다. 만난 자리에 글자가 하나 더 있다.<br>양쪽에서 읽어야만 보이는 글자다. 탑에서 본 것과 같은 수법이다.<br><br>그 글자만 둘 다 안 읽었다. 보기만 했다.<br>보는 건 괜찮다. 읽는 게 안 되는 것이다.`,
        failText:`혼자 두 번 읽었다. 바로 한 번, 거꾸로 한 번.<br><br>두 번째 읽을 때 목이 잠긴다.<br>세 번째 뜻은 안 읽었다.` },
      good:`한 번에 끝냈다.`, bad:`두 번 걸렸다.`, flag:'readSimultaneously' },
    { l:'② 수면의 글자 수를 센다.', mini:'beat', miniOpt:{ p:750, total:12, gap:700 },
      good:`글자를 하나씩 세었다. 열두 번.<br><br>스물셋이다. 또 그 수다.<br>거꾸로 세도 스물셋이다.<br><br>다만 가운데 하나는 두 번 세어진다. 양쪽 다에 속한다.`, flag:'sharedGlyph',
      bad:`세다가 수가 늘어난다.<br><br>세는 동안 글자가 생긴다.<br>그만 셌다.` }
  ] }
);

epicSlot('village', 'mage').push(
{ title:'빈 마을 — 둘이 다시 붙인다',
  text:`부적 한 장이 바깥을 향해 있다.<br><br>
    돌아간 것이다. 돌아간 부적은 효력이 뒤집힌다.<br>
    혼자 돌리면 떼었다 붙여야 한다.<br><br>
    떼는 순간이 위험하다.`,
  opts:[
    { l:'① 동료가 문을 누른다.', co:'standin',
      coOpt:{ ask:'문을 몸으로 눌러 주십시오. 제가 부적을 돌리겠습니다.', sec:60, p:1050,
        text:`떼는 순간이 위험하다.`,
        doneText:`저쪽이 어깨로 문을 눌렀다. 이쪽이 부적을 떼어 돌려 붙였다.<br><br>떼는 순간 문이 밀린다. 저쪽이 버텼다.<br>붙이자 멎었다.<br><br>저쪽 어깨가 젖어 있다. 땀이 아니다.<br>안 물어봤다.`,
        failText:`혼자 떼어 돌렸다. 떼는 순간 문이 밀린다.<br><br>손으로 막으면서 붙였다. 삐뚜름하게 붙었다.<br>삐뚠 부적이 제대로 드는지는 모르겠다.` },
      good:`바로 붙였다.`, bad:`삐뚤게 붙였다.`, flag:'reorientedWard' },
    { l:'② 부적 상태를 견준다.', mini:'scale', miniOpt:{ p:750, target:20, pool:[2,4,5,7,9,11] },
      good:`종이가 삭은 정도를 견줬다.<br><br>맞췄다. 스물둘이 비슷하고 하나만 새것이다.<br>돌아간 그 한 장이다.<br><br>돌아간 게 아니라 나중에 갈아 붙인 것이다. 누가.`, flag:'replacedWard',
      bad:`삭은 정도가 제각각이다.<br><br>여러 번 갈았다. 어느 게 원래인지 모르겠다.<br>그만뒀다.` }
  ] }
);

epicSlot('market', 'mage').push(
{ title:'장터 — 나눠 가진다',
  text:`백지 부적이 스물셋 장이다.<br><br>
    한 사람이 다 가지면 쓰게 된다.<br>
    마법사는 자기를 못 믿는다. 그게 제일 먼저 배우는 것이다.<br><br>
    나눠 가지면 덜 쓴다.`,
  opts:[
    { l:'① 동료와 나눠 가진다.', co:'handoff',
      coOpt:{ ask:'몇 장 맡아 주십시오. 제가 다 가지면 쓰게 됩니다.', sec:55, p:950,
        text:`나눠 가지면 덜 쓴다.`,
        doneText:`다섯 장을 건넸다. 이쪽은 두 장만 챙겼다.<br><br>저쪽이 왜 자기가 더 갖냐고 물었다.<br>쓸 줄 모르는 사람이 갖는 게 안전하다고 했다.<br><br>저쪽이 웃으며 품에 넣었다.<br>웃을 일인지는 모르겠지만 웃어 주니 좋았다.`,
        failText:`혼자 일곱 장을 챙겼다.<br><br>품이 두툼하다. 두툼한 게 계속 신경 쓰인다.<br>안 쓸 생각인데 손이 자꾸 간다.` },
      good:`나눠 가졌다.`, bad:`혼자 가졌다.`, flag:'splitWards' },
    { l:'② 종이 결을 짚는다.', mini:'star', miniOpt:{ p:750, n:6, sec:17 },
      good:`결이 촘촘한 순서로 여섯 장을 짚었다.<br><br>맞췄다. 뒤로 갈수록 성기다.<br>같은 사람이 만들면서 재료가 떨어진 것이다.<br><br>마지막 장은 결이 거의 없다. 급하게 만들었다.`, flag:'thinningPaper',
      bad:`결이 다 비슷하다.<br><br>짚을 수가 없다.<br>그만뒀다.` }
  ] }
);

epicSlot('road', 'mage').push(
{ title:'끊긴 길 — 둘이 확인한다',
  text:`끝 글자가 닫는 글자였다.<br><br>
    닫는 것과 여는 것은 획 하나 차이다.<br>
    혼자 보면 보고 싶은 쪽으로 보인다.<br><br>
    둘이 보면 갈린다.`,
  opts:[
    { l:'① 동료에게 모양을 묻는다.', co:'witness',
      coOpt:{ ask:'이 글자 마지막 획이 어느 쪽으로 휩니까. 글자는 모르셔도 됩니다.', sec:60, p:1000,
        text:`혼자 보면 보고 싶은 쪽으로 보인다.`,
        doneText:`저쪽에게 획 방향만 물었다. 글자인 줄도 모르는 채로.<br><br>왼쪽으로 휜다고 했다. 이쪽이 본 것과 같다.<br>닫는 글자가 맞다.<br><br>글자를 모르는 사람이 본 모양이 제일 믿을 만하다.<br>뜻을 아는 눈은 뜻대로 본다.`,
        failText:`혼자 세 번 봤다. 세 번 다 닫는 쪽으로 보인다.<br><br>세 번 다 이쪽 눈이니 세 번 다 같을 수밖에 없다.<br>믿을 수가 없다.` },
      good:`닫는 글자가 맞았다.`, bad:`확인이 안 됐다.`, flag:'confirmedClosing' },
    { l:'② 돌을 겨눠 던진다.', mini:'aim', miniOpt:{ p:750, shots:3, need:2 },
      good:`문장 새긴 돌 너머로 던졌다. 두 번 맞았다.<br><br>돌이 문장 선을 넘어가면 소리가 안 난다.<br>넘기 전에는 난다.<br><br>문장이 경계다. 글자가 선을 긋고 있다.`, flag:'glyphIsBorder',
      bad:`세 번 다 선 너머로 갔다.<br><br>소리가 하나도 안 났다.<br>돌을 잃었다.` }
  ] }
);
;

